from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 300, "משטח ומאוורר: תיבה במסה 2 קילוגרם בנקודה A על הקרקע. המסילה עולה לקטע אופקי BD באורך 4 מטר בגובה 0.8 מטר. המאוורר בנקודה D מפעיל כוח F שמאלה. וגרף F כפונקציה של x: קו ישר מ-0 ב-B עד 8 ניוטון ב-4 מטר")
    g.path("M 30,140 L 140,140 Q 190,140 210,100 Q 230,70 260,70 L 470,70", width=2.5)
    g.block(70, 128, 26, 20, "m"); g.text(70, 160, "A")
    for x, t in ((260, "B"), (365, "C"), (470, "D")): g.dot(x, 70); g.text(x, 92, t)
    g.dim(260, 108, 470, 108, "4m", offset=0); g.dim(500, 70, 500, 140, "h = 0.8 m", offset=0)
    g.line(30, 140, 520, 140, stroke="var(--d-dim)", width=1, dash="4 3")
    g.circle(480, 46, 10, fill="var(--d-fill)", stroke="var(--d-line)"); g.arrow(460, 40, 420, 40, "F", lx=430, ly=32)
    X, Y = g.graph(200, 280, 200, 100, "x (m)", "F (N)", xticks=[(v, str(v)) for v in (1, 2, 3, 4)], yticks=[(v, str(v)) for v in (2, 4, 6, 8)], xmax=4.3, ymax=8.5)
    g.plot(X, Y, [(0, 0), (4, 8)])
    return g

E(id="bagrut-2019-q4", year=2019, label="2019 שאלה 4", topic="energy", sub="en-work", diff=3, fig=fig,
  stem=r"תלמיד חוקר אנרגיה מכנית בעזרת תיבה שמסתה $m = 2\,\text{kg}$, משטח $AD$ ומאוורר. הקטע $BD$ אופקי, באורך $4\,\text{m}$, ובגובה $h = 0.8\,\text{m}$ מעל הקרקע. מזניחים את החיכוך בין התיבה למשטח. התלמיד שם את התיבה בנקודה $A$ ואת המאוורר בנקודה $D$. המאוורר יוצר רוח אופקית. הכוח $F$ שהרוח מפעילה על התיבה גדל בקו ישר עם המרחק $x$ של התיבה מהנקודה $B$, כמו בגרף: הוא אפס ב-$B$ ומרבי ב-$D$. משמאל ל-$B$ הרוח לא משפיעה. מתחשבים רק בהשפעה של הרוח מהמאוורר, ומזניחים כל השפעה אחרת של האוויר.",
  parts=[
    P("א", r"מה גודל המהירות המזערית שצריך לתת לתיבה בנקודה $A$, כדי שתעלה במשטח ותגיע לנקודה $B$?", num(4, "m/s"), ["principle"], [
        S(r"שימור אנרגיה", r"במהירות המזערית התיבה מגיעה לנקודה בדיוק, במהירות אפס. המסה מצטמצמת", r"\tfrac{1}{2}m\,v^2 = m \cdot 10 \cdot 0.8 \;\Rightarrow\; v = \sqrt{16} = 4\,\text{m/s}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
    ], r"$4\,\text{m/s}$", key=r"v=4 m/s"),
    P("ב", r"התלמיד נותן לתיבה בנקודה $A$ מהירות $v_0 = 5\,\text{m/s}$ ימינה. כשהתיבה מגיעה ל-$B$ הכוח $F(x)$ מתחיל לפעול עליה, ובנקודה $C$ היא נעצרת לרגע. מה העבודה של הכוח $F(x)$ מ-$B$ עד $C$?", num(-9, "J"), ["principle", "signs"], [
        S(r"האנרגיה הקינטית בנקודה B", r"שימור אנרגיה מהנקודה הראשונה. חלק מהאנרגיה הקינטית הפך לאנרגיית גובה", r"E_{k,B} = \tfrac{1}{2} \cdot 2 \cdot 5^2 - 2 \cdot 10 \cdot 0.8 = 25 - 16 = 9\,\text{J}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"משפט העבודה והאנרגיה", r"בקטע הזה רק הכוח של הרוח עושה עבודה. הכובד והכוח הנורמלי ניצבים לתנועה. התיבה נעצרת בסוף", r"W_F = 0 - 9 = -9\,\text{J}", eq=r"W_{\text{tot}} = \Delta E_k"),
    ], r"$-9\,\text{J}$", key=r"w=−9 J"),
    P("ג", r"מה המרחק בין הנקודה $C$ לנקודה $B$?", num(3, "m"), ["graph", "algebra"], [
        S(r"הכוח לפי הגרף", r"קו ישר מאפס עד שמונה ניוטון בארבעה מטרים", r"F = \frac{8}{4}\,x = 2x"),
        S(r"העבודה היא השטח מתחת לגרף", r"השטח מתחת לקו, עד הנקודה שבה התיבה נעצרת, הוא משולש. הכוח נגד התנועה, ולכן העבודה שלילית", r"|W_F| = \tfrac{1}{2} \cdot x \cdot 2x = x^2"),
        S(r"פותרים", r"השטח שווה לגודל העבודה מהסעיף הקודם", r"x^2 = 9 \;\Rightarrow\; x = 3\,\text{m}"),
    ], r"$3\,\text{m}$", key=r"x=3 m"),
    P("ד", r"אחרי שהתיבה נעצרת לרגע ב-$C$, היא נעה חזרה אל $B$. תארו במילים את התנועה שלה מ-$C$ עד $B$: האם היא במהירות קבועה או בתאוצה, האם התאוצה קבועה או משתנה, והאם גודל המהירות גדל או קטן.", OPEN, ["principle"], [
        S(r"הכוח", r"הכוח של הרוח בכיוון התנועה, וקטן ככל שהתיבה מתקרבת לנקודה שבה הרוח מתאפסת", r"F = 2x"),
        S(r"התנועה", r"לפי החוק השני התאוצה היא הכוח חלקי המסה. הכוח קטן, ולכן התאוצה קטנה. התאוצה בכיוון התנועה, ולכן המהירות גדלה", r"a = \frac{F}{m} = x", eq=r"\Sigma\vec F = m\vec a"),
    ], r"בתאוצה שהולכת וקטנה, וגודל המהירות גדל", key=r"מואצת, תאוצה קטנה, מהירות גדלה"),
    P("ה", r"מה גודל המהירות של התיבה כשהיא חוזרת לנקודה $A$? נמקו, והתייחסו גם לכוחות הלא משמרים במערכת.", num(5, "m/s"), ["principle"], [
        S(r"הכוח של הרוח תלוי רק במקום", r"בדרך חזרה הכוח בכל מקום זהה לדרך הלוך, אבל התנועה הפוכה. לכן העבודה בחזרה מבטלת את העבודה בהלוך", r"W_F + W_F' = -9 + 9 = 0"),
        S(r"מסקנה", r"אין חיכוך, ולכן בסך הכול אף כוח לא משמר לא עשה עבודה. התיבה חוזרת לאותו גובה עם אותה אנרגיה", r"W_{\text{nc}} = 0 \;\Rightarrow\; v_A = 5\,\text{m/s}", eq=r"W_{\text{nc}} = \Delta E"),
    ], r"$5\,\text{m/s}$", key=r"vA=5 m/s"),
  ],
  concepts=["משפט העבודה והאנרגיה", "כוח משתנה", "שטח מתחת לגרף כוח-מקום", "שימור אנרגיה"],
  summary=r"תיבה שנבלמת ברוח של מאוורר, שחזקה יותר ככל שמתקרבים אליו: עבודה כשטח מתחת לגרף, נקודת העצירה, ולמה התיבה חוזרת באותה מהירות.",
  review="הנחה שלי.\nמה לבדוק: רק לאשר.")
